    Queue<TreeNode> nodesToRemove = new LinkedList<>();
    Deque<TreeNode> nodesToVisit = new LinkedList<>();
    nodesToVisit.offer(rootNode);

    while (!nodesToVisit.isEmpty()) {
        TreeNode node = nodesToVisit.poll();
        if (node.isUsed()) {
            nodesToRemove.offer(node);
        } else {
            // Visit all children
            for (TreeNode child : node.getChildren()) {
                nodesToVisit.offer(child);
            }
        }
    }

    while (!nodesToRemove.isEmpty()) {
        TreeNode node = nodesToRemove.poll();
        // Remove from the category tree
        removeNode(node);
    }

    return nodesToRemove.size();
}

