    // Check if the graph only has one node
    if(graph.orderSize() == 1) return true;

    // Initialize all vertices as not visited
    List<V> visited = new ArrayList<>(vertices);
    visited.forEach(v -> v.setStatus(false));

    // Check each vertex if it can be included in the clique
    for(V vertex : vertices) {
        List<V> in Degrees = new ArrayList<>(graph.inningEdgesOf(vertex));
        inDegrees.forEach(edge -> {
            V oppositeVertex = graph.getOppositeVertex(edge, vertex);
            if(visited.stream().noneMatch(v -> v.equals(oppositeVertex))) {
                visited.clear(); // Reset visited for each potential independent set of vertices
                for(V v : vertices){
                    v.setStatus(edge.getId() % 2 == 1); // Assign a status based on the edge's parity
                }
                if(inDegrees.stream().allMatch(v -> visited.contains(v))) {
                    return true; // If all in-degrees are satisfied, return true
                }
            }
        });
        break; // Early exit as we found a clique
    }
    return false; // No clique found
}

