public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

        // Read file content
        BufferedReader reader = new BufferedReader(new FileReader(file));
        String line;
        while ((line = reader.readLine()) != null) {
            String[] constraints = line.split(",+");
            if (constraints.length != 7) {
                continue; // Skip lines with incorrect数量的constraints
            }

            String threadSnapshotStr = constraints[0];
            ProfileAnalyzeTimeRange timeRange = ProfileAnalyzeTimeRange.fromString(constraints[1], constraints[2], constraints[3], constraints[4], constraints[5]);
            String mode = constraints[6];

            // Parse frame data based on mode
            FrameData frameData;
            if (mode.equals("thread")) {
                frameData = new ThreadFrameData();
            } else if (mode.equals("class")) {
                frameData = new ClassFrameData();
            } else if (mode.equals("function")) {
                frameData = new FunctionFrameData();
            } else {
                throw new IllegalArgumentException("Unsupported mode: " + mode);
            }

            // Add thread snapshot to list
            threadSnapshots.add(new ThreadSnapshot(threadSnapshotStr, span, frameData));
        }

        reader.close();
        return threadSnapshots;
    }

